	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void serializableReplayRetainsObservationForPrepareValidation(@TempDir Path dataDirectory) throws Exception {
		LmdbStore store = newStore(dataDirectory);
		store.init();
		IRI observedSubject = VF.createIRI("urn:lmdb:replay-lifecycle:observed-subject");
		IRI localWriteSubject = VF.createIRI("urn:lmdb:replay-lifecycle:local-write-subject");
		IRI localWritePredicate = VF.createIRI("urn:lmdb:replay-lifecycle:local-write-predicate");
		try {
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(observedSubject, FIRST_PREDICATE, VF.createLiteral("seed"));
				seed.commit();
			}

			TripleStore tripleStore = tripleStoreOf(store);
			long initialMapSize = mapSize(tripleStore);
			String namespace = growthNamespace(initialMapSize);
			LmdbSailStore backingStore = store.getBackingStore();
			MapGrowthMetrics.Snapshot before = backingStore.growthMetricsSnapshot();
			try (SailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SERIALIZABLE);
				try (CloseableIteration<? extends Statement> results = reader.getStatements(observedSubject,
						FIRST_PREDICATE, null, false)) {
					try (SailConnection growthWriter = store.getConnection()) {
						growthWriter.begin(IsolationLevels.SNAPSHOT);
						addGrowthStatements(growthWriter, initialMapSize);
						growthWriter.commit();
					}
					awaitGrowthEpisode(backingStore, before);
					try (SailConnection barrier = store.getConnection()) {
						barrier.begin(IsolationLevels.SNAPSHOT);
						assertEquals(namespace, barrier.getNamespace("growth-demand"));
						barrier.rollback();
					}
					assertTrue(mapSize(tripleStore) > initialMapSize,
							"the unobserved SERIALIZABLE result must span actual TripleStore growth");

					assertTrue(results.hasNext(), "the replayed statement pattern must find its seeded row");
					assertEquals("seed", results.next().getObject().stringValue());
					assertFalse(results.hasNext());
				}

				reader.addStatement(localWriteSubject, localWritePredicate, VF.createLiteral("reader-write"));
				try (SailConnection conflictingWriter = store.getConnection()) {
					conflictingWriter.begin(IsolationLevels.SNAPSHOT);
					conflictingWriter.addStatement(observedSubject, FIRST_PREDICATE,
							VF.createLiteral("concurrent-write"));
					conflictingWriter.commit();
				}

				assertThrows(SailConflictException.class, () -> {
					reader.prepare();
					reader.commit();
				}, "replay must preserve the SERIALIZABLE read pattern for prepare-time validation");
				if (reader.isActive()) {
					reader.rollback();
				}
			}
		} finally {
			store.shutDown();
		}
	}

	@Test
	@Timeout(value = 45, unit = TimeUnit.SECONDS)
	void activeSnapshotSortReplaysAfterGracefulGrowthBeforeFirstResultEscapes(@TempDir Path dataDirectory)
			throws Exception {
		String functionIri = "urn:lmdb:replay-lifecycle:sort-barrier:" + UUID.randomUUID();
		SortReplayBarrierFunction function = new SortReplayBarrierFunction(functionIri);
		FunctionRegistry functionRegistry = FunctionRegistry.getInstance();
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), new LmdbStoreConfig("spoc,posc")
				.setForceSync(true)
				.setTripleDBSize(INITIAL_MAP_SIZE)
				.setValueDBSize(128L * 1024L * 1024L)
				.setMapGrowthThreshold(GROWTH_THRESHOLD)
				.setMapGrowthReadDrainTimeoutMillis(150)
				.setAutoGrow(true));
		SailRepository repository = new SailRepository(store);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			functionRegistry.add(function);
			repository.init();
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(FIRST_SUBJECT, FIRST_PREDICATE, VF.createLiteral("a-before"));
				seed.addStatement(FIRST_SUBJECT, FIRST_PREDICATE, VF.createLiteral("b-before"));
				seed.commit();
			}

			LmdbSailStore backingStore = store.getBackingStore();
			TripleStore tripleStore = tripleStoreOf(store);
			long initialMapSize = mapSize(tripleStore);
			String namespace = hardGrowthNamespace(backingStore, initialMapSize);
			MapGrowthMetrics.Snapshot before = backingStore.growthMetricsSnapshot();
			assertFalse(backingStore.growthAdmissionClosed(), "the store must start outside a growth episode");
			Future<List<String>> query = executor.submit(() -> {
				try (RepositoryConnection reader = repository.getConnection()) {
					reader.begin(IsolationLevels.SNAPSHOT);
					TupleQuery tupleQuery = reader.prepareTupleQuery(QueryLanguage.SPARQL,
							"SELECT ?value WHERE { <" + FIRST_SUBJECT.stringValue() + "> <"
									+ FIRST_PREDICATE.stringValue() + "> ?value } ORDER BY <" + functionIri
									+ ">(?value)");
					List<String> values = new ArrayList<>();
					try (TupleQueryResult results = tupleQuery.evaluate()) {
						while (results.hasNext()) {
							values.add(results.next().getValue("value").stringValue());
						}
					}
					reader.commit();
					return values;
				}
			});

			assertTrue(function.awaitFirstInvocation(), "ORDER BY must block while the result is still unobserved");
			Future<?> writer = executor.submit(() -> {
				try (SailConnection growthWriter = store.getConnection()) {
					growthWriter.begin(IsolationLevels.SNAPSHOT);
					addGrowthStatements(growthWriter, 10_000, namespace);
					growthWriter.addStatement(FIRST_SUBJECT, FIRST_PREDICATE, VF.createLiteral("z-after"));
					growthWriter.commit();
				}
				return null;
			});
			awaitStartedGrowthAdmissionClosure(backingStore, before, writer);
			awaitReplayAccepted(backingStore, before, writer);
			function.releaseFirstInvocation();

			writer.get(20, TimeUnit.SECONDS);
			List<String> values = query.get(20, TimeUnit.SECONDS);
			awaitTripleStoreGrowth(repository, tripleStore, initialMapSize, namespace);
			MapGrowthMetrics.Snapshot after = backingStore.growthMetricsSnapshot();
			assertTrue(mapSize(tripleStore) > initialMapSize, "the writer must complete real TripleStore map growth");
			assertEquals(before.valueStoreResizes(), after.valueStoreResizes(),
					"the complete input must fit the other environment without dictionary growth");
			assertThat(values).containsExactlyInAnyOrder("a-before", "b-before", "z-after");
			assertEquals(before.replayAccepted() + 1, after.replayAccepted(),
					"the active snapshot sort must be accepted for exactly one whole-transaction replay");
			assertEquals(before.forcedInvalidationEpisodes(), after.forcedInvalidationEpisodes(),
					"the sort must release its old read view before bounded drain fallback");
			assertEquals(before.forcedInvalidatedViews(), after.forcedInvalidatedViews(),
					"graceful replay must not force-invalidate a read view");
			assertTrue(function.invocationCount() > 2,
					"the ORDER BY expression must execute again after publication on the replacement snapshot");
			assertFalse(backingStore.growthAdmissionClosed(), "completed publication must reopen read admission");
		} finally {
			function.releaseFirstInvocation();
			executor.shutdownNow();
			try {
				assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS), "sort and growth workers must terminate");
			} finally {
				functionRegistry.remove(function);
				repository.shutDown();
			}
		}
	}

